#[derive(Debug, Clone, Serialize)]
pub struct RankedMatch {
    pub file_id: String,
    pub symbol_id: Option<String>,
    pub score: i32,
    pub why: Vec<String>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub score_debug: Vec<ScoreComponent>,
}

