fn parse_c_line(line: &str) -> Option<(String, String, String)> {
    parse_c_style_line(
        line,
        &["static", "inline", "extern", "const", "volatile"],
        &[
            ("struct ", "struct"),
            ("enum ", "enum"),
            ("typedef ", "type"),
        ],
