        #[arg(long, value_enum, default_value_t = EmbedModelArg::Small)]
        embed_model: EmbedModelArg,
    },

    /// List indexed symbols.
    Symbols {
        path: PathBuf,

        #[arg(long, default_value_t = 100)]
