            (Some(symbol), Some(line)) => format!("{symbol} at line {line}"),
            (Some(symbol), None) => symbol.to_string(),
            (None, Some(line)) => format!("line {line}"),
            (None, None) => String::new(),
        };
        return Err(anyhow!(
            "symbol selector was not found in indexed file {file_path}: {selector}"
        ));
    }
