fn expand_compact_symbol_kind(kind: &str) -> &str {
    match kind {
        "cl" => "class",
        "m" => "method",
        "if" => "interface",
        "t" => "type",
        "s" => "struct",
        "e" => "enum",
        "tr" => "trait",
        "im" => "impl",
        "c" => "constant",
        "mod" => "module",
        "mac" => "macro",
        "cmp" => "component",
        _ => kind,
    }
}

