        .find(|file| file.file == "src/auth/session.ts")
        .unwrap();

    assert!(
        session_file
            .blast_radius
            .imports
            .contains(&"src/auth/token.ts".to_string())
    );
    assert!(
        session_file
            .blast_radius
            .referenced_by
            .contains(&"src/auth/session.test.ts".to_string())
    );
    assert!(
        session_file
            .blast_radius
            .tests
            .contains(&"src/auth/session.test.ts".to_string())
    );
    assert_eq!(session_file.blast_radius.risk, "medium");
}

